        files = changed_files(base, requested_paths)
    except GitError as exc:
        raise SystemExit(f'Failed to determine changed files: {exc}') from exc
    if not files:
        run_scan(ScanOptions(paths=[], fmt=fmt, out_path=out_path, engine_name=engine_name, embedder=embedder, index=index, device=device))
