    __import__('clonehunter.engines')
    overrides = build_base_overrides(engine_name=engine_name, embedder=embedder, index=index, device=device, env_embedder=os.environ.get('CLONEHUNTER_EMBEDDER'))
    config = load_config(Path.cwd(), clean_overrides(overrides))
    engine = get_engine(config.engine)
    result = engine.scan(ScanRequest(paths=requested_paths, config=config))
    changed = {_normalize_repo_path(file_path) for file_path in files}
    filtered = [f for f in result.findings if _normalize_repo_path(f.function_a.file.path) in changed or _normalize_repo_path(f.function_b.file.path) in changed]
    stats = replace(result.stats, finding_count=len(filtered))
    filtered_result = ScanResult(findings=filtered, stats=stats, config_snapshot=result.config_snapshot, timing=result.timing)
